import { useFrame } from "@react-three/fiber";
import { useRef } from "react";
import * as THREE from "three";
import GameLights from "./GameLights";
import KnirvGraph from "./KnirvGraph";
import CameraController from "./CameraController";
import { useKnirvana } from "../../lib/stores/useKnirvana";

export default function GameScene() {
  const sceneRef = useRef<THREE.Group>(null);
  const { gameTime } = useKnirvana();

  useFrame((state, delta) => {
    // Update game time
    useKnirvana.getState().updateGameTime(delta);

    // Subtle scene rotation for dynamic feel
    if (sceneRef.current) {
      sceneRef.current.rotation.y += delta * 0.02;
    }
  });

  return (
    <group ref={sceneRef}>
      <GameLights />
      <CameraController />

      {/* Ground plane with TRON grid */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.1, 0]} receiveShadow>
        <planeGeometry args={[100, 100, 50, 50]} />
        <meshStandardMaterial 
          color="#001122" 
          wireframe={true}
          transparent={true}
          opacity={0.3}
        />
      </mesh>

      {/* KNIRV Graph representation */}
      <KnirvGraph />

      {/* Ambient particles */}
      <mesh>
        <bufferGeometry>
          <bufferAttribute
            attach="attributes-position"
            count={1000}
            array={new Float32Array(
              Array.from({ length: 3000 }, () => (Math.random() - 0.5) * 200)
            )}
            itemSize={3}
          />
        </bufferGeometry>
        <pointsMaterial 
          size={0.1} 
          color="#00ffff" 
          transparent={true}
          opacity={0.5}
          sizeAttenuation={true}
        />
      </mesh>
    </group>
  );
}

