import React, { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { useKnirvana } from '../../lib/stores/useKnirvana';

export default function NetworkVisualization() {
  const { errorNodes, skillNodes, gameTime } = useKnirvana();
  const connectionLinesRef = useRef<THREE.Group>(null);
  const dataFlowRef = useRef<THREE.Points>(null);

  useFrame((state) => {
    // Animate network connections
    if (connectionLinesRef.current) {
      connectionLinesRef.current.children.forEach((line, index) => {
        const material = (line as THREE.Mesh).material as THREE.LineBasicMaterial;
        material.opacity = 0.3 + Math.sin(state.clock.elapsedTime * 2 + index) * 0.2;
      });
    }

    // Animate data flow particles
    if (dataFlowRef.current) {
      const positions = dataFlowRef.current.geometry.attributes.position.array as Float32Array;
      for (let i = 0; i < positions.length; i += 3) {
        positions[i + 1] += Math.sin(state.clock.elapsedTime + i) * 0.01;
      }
      dataFlowRef.current.geometry.attributes.position.needsUpdate = true;
    }
  });

  // Generate connection lines between nodes
  const generateConnections = () => {
    const connections = [];
    const allNodes = [...errorNodes, ...skillNodes];

    for (let i = 0; i < allNodes.length - 1; i++) {
      for (let j = i + 1; j < Math.min(i + 3, allNodes.length); j++) {
        const nodeA = allNodes[i];
        const nodeB = allNodes[j];

        const distance = Math.sqrt(
          Math.pow(nodeA.position.x - nodeB.position.x, 2) +
          Math.pow(nodeA.position.z - nodeB.position.z, 2)
        );

        // Only connect nearby nodes
        if (distance < 8) {
          const geometry = new THREE.BufferGeometry().setFromPoints([
            new THREE.Vector3(nodeA.position.x, nodeA.position.y + 0.5, nodeA.position.z),
            new THREE.Vector3(nodeB.position.x, nodeB.position.y + 0.5, nodeB.position.z)
          ]);

          connections.push(
            <line key={`connection-${i}-${j}`} geometry={geometry}>
              <lineBasicMaterial 
                color="#004477" 
                transparent 
                opacity={0.3}
              />
            </line>
          );
        }
      }
    }
    return connections;
  };

  // Generate data flow particles
  const generateDataFlow = () => {
    const particleCount = 200;
    const particles = new Float32Array(particleCount * 3);

    for (let i = 0; i < particleCount * 3; i += 3) {
      particles[i] = (Math.random() - 0.5) * 40;     // x
      particles[i + 1] = Math.random() * 20 + 1;     // y  
      particles[i + 2] = (Math.random() - 0.5) * 40; // z
    }

    return particles;
  };

  return (
    <group>
      {/* Network connection lines */}
      <group ref={connectionLinesRef}>
        {generateConnections()}
      </group>

      {/* Data flow visualization */}
      <points ref={dataFlowRef}>
        <bufferGeometry>
          <bufferAttribute
            attach="attributes-position"
            count={200}
            array={generateDataFlow()}
            itemSize={3}
          />
        </bufferGeometry>
        <pointsMaterial 
          size={0.02}
          color="#0088cc"
          transparent
          opacity={0.6}
          sizeAttenuation={true}
        />
      </points>

      {/* Network health visualization */}
      <mesh position={[0, 25, 0]}>
        <sphereGeometry args={[0.5, 16, 16]} />
        <meshStandardMaterial
          color="#00ffff"
          emissive="#00ffff"
          emissiveIntensity={0.4 + Math.sin(gameTime * 0.01) * 0.2}
          transparent
          opacity={0.8}
        />
      </mesh>

      {/* Data streams from central node */}
      {[0, 60, 120, 180, 240, 300].map((angle, index) => (
        <group key={`stream-${index}`} rotation={[0, (angle * Math.PI) / 180, 0]}>
          <mesh position={[0, 25, 15]}>
            <cylinderGeometry args={[0.01, 0.01, 20]} />
            <meshBasicMaterial 
              color="#0066cc"
              transparent
              opacity={0.4}
            />
          </mesh>
        </group>
      ))}

      {/* Knowledge graph grid overlay */}
      <mesh rotation={[Math.PI / 2, 0, 0]} position={[0, 0.1, 0]}>
        <planeGeometry args={[60, 60, 20, 20]} />
        <meshBasicMaterial 
          color="#002244"
          transparent
          opacity={0.1}
          wireframe
        />
      </mesh>

      {/* Sector boundary indicators */}
      {[-15, -5, 5, 15].map((x, i) =>
        [-15, -5, 5, 15].map((z, j) => (
          <mesh key={`sector-${i}-${j}`} position={[x, 0.2, z]}>
            <cylinderGeometry args={[0.1, 0.1, 0.2]} />
            <meshBasicMaterial 
              color="#003366"
              transparent
              opacity={0.5}
            />
          </mesh>
        ))
      )}
    </group>
  );
}

client/src/components/game/PretrainingIn.content:
import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Progress } from '../ui/progress';
import { useKnirvana } from '../../lib/stores/useKnirvana';

interface PretrainingSkill {
  id: string;
  name: string;
  category: 'Analysis' | 'Optimization' | 'Synthesis' | 'Debug';
  description: string;
  nrnCost: number;
  trainingTime: number;
  effectiveness: number;
}

export default function PretrainingInterface() {
  const [isOpen, setIsOpen] = useState(false);
  const [selectedAgent, setSelectedAgent] = useState<string | null>(null);
  const [trainingProgress, setTrainingProgress] = useState<{ [key: string]: number }>({});
  const { agents, nrnBalance, spendNRN } = useKnirvana();

  const availableSkills: PretrainingSkill[] = [
    {
      id: 'pattern-analysis',
      name: 'Advanced Pattern Analysis',
      category: 'Analysis',
      description: 'Improves agent ability to identify complex error patterns in KNIRVGRAPH',
      nrnCost: 35,
      trainingTime: 15,
      effectiveness: 0.25
    },
    {
      id: 'neural-optimization',
      name: 'Neural Path Optimization',
      category: 'Optimization', 
      description: 'Enhances solution path finding and computational efficiency',
      nrnCost: 45,
      trainingTime: 20,
      effectiveness: 0.3
    },
    {
      id: 'knowledge-synthesis',
      name: 'Knowledge Synthesis',
      category: 'Synthesis',
      description: 'Enables creation of new SkillNodes from resolved ErrorNodes',
      nrnCost: 55,
      trainingTime: 25,
      effectiveness: 0.35
    },
    {
      id: 'deep-debugging',
      name: 'Deep System Debugging',
      category: 'Debug',
      description: 'Specialized in resolving high-difficulty system ErrorNodes',
      nrnCost: 65,
      trainingTime: 30,
      effectiveness: 0.4
    }
  ];

  const startTraining = (agentId: string, skillId: string) => {
    const skill = availableSkills.find(s => s.id === skillId);
    if (!skill) return;

    if (spendNRN(skill.nrnCost)) {
      const trainingKey = `${agentId}-${skillId}`;
      setTrainingProgress(prev => ({ ...prev, [trainingKey]: 0 }));

      // Simulate training progress
      const interval = setInterval(() => {
        setTrainingProgress(prev => {
          const currentProgress = prev[trainingKey] || 0;
          const newProgress = currentProgress + (100 / skill.trainingTime);

          if (newProgress >= 100) {
            clearInterval(interval);
            // Training completed - would update agent capabilities here
            console.log(`Agent ${agentId} completed training: ${skill.name}`);
            return { ...prev, [trainingKey]: 100 };
          }

          return { ...prev, [trainingKey]: newProgress };
        });
      }, 1000);
    }
  };

  if (!isOpen) {
    return (
      <div className="absolute bottom-4 left-4 pointer-events-auto">
        <Button
          onClick={() => setIsOpen(true)}
          className="bg-purple-600 hover:bg-purple-700 text-white"
        >
          Pre-train Agents
        </Button>
      </div>
    );
  }

  return (
    <div className="absolute inset-0 bg-black bg-opacity-50 flex items-center justify-center pointer-events-auto">
      <Card className="w-96 max-h-[80vh] overflow-y-auto bg-black bg-opacity-95 border-purple-500">
        <CardHeader>
          <CardTitle className="text-purple-400 flex items-center justify-between">
            Agent Pre-training Center
            <Button
              onClick={() => setIsOpen(false)}
              size="sm"
              className="bg-gray-700 hover:bg-gray-600"
            >
              ×
            </Button>
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Agent Selection */}
          <div>
            <h3 className="text-cyan-400 mb-2">Select Agent to Train:</h3>
            <div className="grid grid-cols-2 gap-2">
              {agents.map(agent => (
                <Button
                  key={agent.id}
                  onClick={() => setSelectedAgent(agent.id)}
                  className={`text-xs p-2 ${
                    selectedAgent === agent.id
                      ? 'bg-cyan-600 hover:bg-cyan-700'
                      : 'bg-gray-700 hover:bg-gray-600'
                  }`}
                >
                  {agent.type} Agent
                  <div className="text-xs opacity-80">
                    Eff: {Math.round(agent.efficiency * 100)}%
                  </div>
                </Button>
              ))}
            </div>
          </div>

          {/* Available Skills */}
          {selectedAgent && (
            <div>
              <h3 className="text-cyan-400 mb-2">Available Training Skills:</h3>
              <div className="space-y-3">
                {availableSkills.map(skill => {
                  const trainingKey = `${selectedAgent}-${skill.id}`;
                  const isTraining = trainingProgress[trainingKey] !== undefined && trainingProgress[trainingKey] < 100;
                  const isCompleted = trainingProgress[trainingKey] >= 100;

                  return (
                    <div
                      key={skill.id}
                      className="border border-gray-600 rounded p-3 space-y-2"
                    >
                      <div className="flex items-center justify-between">
                        <h4 className="text-white font-semibold">{skill.name}</h4>
                        <span className={`px-2 py-1 rounded text-xs ${
                          skill.category === 'Analysis' ? 'bg-blue-600' :
                          skill.category === 'Optimization' ? 'bg-green-600' :
                          skill.category === 'Synthesis' ? 'bg-purple-600' :
                          'bg-red-600'
                        }`}>
                          {skill.category}
                        </span>
                      </div>

                      <p className="text-gray-300 text-sm">{skill.description}</p>

                      <div className="flex items-center justify-between text-xs">
                        <span className="text-green-400">Cost: {skill.nrnCost} NRN</span>
                        <span className="text-yellow-400">Time: {skill.trainingTime}s</span>
                        <span className="text-purple-400">Boost: +{Math.round(skill.effectiveness * 100)}%</span>
                      </div>

                      {isTraining && (
                        <div className="space-y-1">
                          <div className="flex justify-between text-xs">
                            <span className="text-cyan-400">Training Progress:</span>
                            <span className="text-white">{Math.round(trainingProgress[trainingKey])}%</span>
                          </div>
                          <Progress 
                            value={trainingProgress[trainingKey]} 
                            className="h-2 bg-gray-700"
                          />
                        </div>
                      )}

                      <Button
                        onClick={() => startTraining(selectedAgent, skill.id)}
                        disabled={nrnBalance < skill.nrnCost || isTraining || isCompleted}
                        className={`w-full text-xs ${
                          isCompleted ? 'bg-green-600 hover:bg-green-700' :
                          isTraining ? 'bg-yellow-600 hover:bg-yellow-700' :
                          'bg-purple-600 hover:bg-purple-700'
                        }`}
                      >
                        {isCompleted ? '✓ Training Complete' :
                         isTraining ? 'Training...' :
                         'Start Training'
                        }
                      </Button>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* NRN Balance */}
          <div className="pt-3 border-t border-gray-700 text-center">
            <div className="text-gray-400 text-sm">Available Balance:</div>
            <div className="text-green-400 font-bold text-lg">{nrnBalance.toFixed(1)} NRN</div>
          </div>
        </CardContent>
      </Card>
    </div>
