import React from 'react';
import { Card, CardContent } from './card';

interface AgentProfileCardProps {
  agentId: string;
  type: string;
  status: 'idle' | 'moving' | 'working' | 'upgrading';
  efficiency: number;
  experience: number;
  isSelected?: boolean;
  onClick?: () => void;
}

export default function AgentProfileCard({
  agentId,
  type,
  status,
  efficiency,
  experience,
  isSelected = false,
  onClick
}: AgentProfileCardProps) {
  const getTypeColor = (agentType: string) => {
    switch (agentType) {
      case 'Analyzer': return 'border-red-500 bg-red-900';
      case 'Optimizer': return 'border-teal-500 bg-teal-900';
      case 'Synthesizer': return 'border-blue-500 bg-blue-900';
      case 'Debugger': return 'border-yellow-500 bg-yellow-900';
      default: return 'border-gray-500 bg-gray-900';
    }
  };

  const getStatusIcon = (agentStatus: string) => {
    switch (agentStatus) {
      case 'working': return '⚡';
      case 'moving': return '🚀';
      case 'upgrading': return '🔧';
      default: return '💤';
    }
  };

  const getExperienceLevel = () => {
    return Math.floor(experience / 25) + 1;
  };

  return (
    <Card 
      className={`w-48 cursor-pointer transition-all duration-200 bg-opacity-90 ${
        isSelected 
          ? `${getTypeColor(type)} ring-2 ring-cyan-400` 
          : `${getTypeColor(type)} bg-opacity-60 hover:bg-opacity-80`
      }`}
      onClick={onClick}
    >
      <CardContent className="p-3">
        <div className="flex items-center space-x-3">
          {/* Agent Avatar */}
          <div className="relative">
            <div className="w-12 h-12 rounded-lg bg-gray-800 border border-cyan-500 flex items-center justify-center overflow-hidden">
              <img 
                src="/textures/agent_avatar.png" 
                alt="Agent Avatar"
                className="w-10 h-10 object-cover"
                style={{
                  filter: `hue-rotate(${
                    type === 'Analyzer' ? '0deg' :
                    type === 'Optimizer' ? '180deg' :
                    type === 'Synthesizer' ? '240deg' :
                    type === 'Debugger' ? '60deg' : '0deg'
                  })`
                }}
              />
            </div>

            {/* Status indicator */}
            <div className="absolute -top-1 -right-1 w-4 h-4 rounded-full bg-black border border-gray-600 flex items-center justify-center text-xs">
              {getStatusIcon(status)}
            </div>
          </div>

          {/* Agent Info */}
          <div className="flex-1 min-w-0">
            <div className="flex items-center justify-between mb-1">
              <h4 className="text-sm font-semibold text-white truncate">
                {type} Agent
              </h4>
              <span className="text-xs text-gray-400">
                L{getExperienceLevel()}
              </span>
            </div>

            <div className="text-xs text-gray-400 mb-1">
              ID: {agentId.slice(-6)}
            </div>

            <div className="flex items-center justify-between text-xs">
              <span className="capitalize text-gray-300">
                {status}
              </span>
              <span className={`font-semibold ${
                efficiency > 0.8 ? 'text-green-400' :
                efficiency > 0.5 ? 'text-yellow-400' :
                'text-red-400'
              }`}>
                {Math.round(efficiency * 100)}%
              </span>
            </div>

            {/* Efficiency bar */}
            <div className="mt-2 w-full bg-gray-700 rounded-full h-1">
              <div 
                className={`h-1 rounded-full transition-all duration-300 ${
                  efficiency > 0.8 ? 'bg-green-400' :
                  efficiency > 0.5 ? 'bg-yellow-400' :
                  'bg-red-400'
                }`}
                style={{ width: `${efficiency * 100}%` }}
              />
            </div>
          </div>
        </div>

        {/* Experience points */}
        <div className="mt-2 flex justify-center space-x-1">
          {Array.from({ length: 5 }, (_, i) => (
            <div
              key={i}
              className={`w-2 h-1 rounded-full ${
                i < getExperienceLevel() ? 'bg-purple-400' : 'bg-gray-600'
              }`}
            />
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

client/src/components/ui/GameHUD.tsx.content:
import React from 'react';
import { useKnirvana } from '../../lib/stores/useKnirvana';
import { Card, CardContent } from './card';
import { Button } from './button';

export default function GameHUD() {
  const { 
    gameTime,
    nrnBalance,
    skillsLearned,
    errorsResolved,
    agents,
    errorNodes,
    skillNodes,
    gamePhase,
    pauseGame,
    startGame
  } = useKnirvana();

  const formatTime = (time: number) => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  };

  const getNetworkHealth = () => {
    const totalNodes = errorNodes.length + skillNodes.length;
    const resolvedNodes = errorNodes.filter(n => n.progress >= 1).length;
    return totalNodes > 0 ? Math.round((resolvedNodes / totalNodes) * 100) : 0;
  };

  const getActiveAgentsCount = () => {
    return agents.filter(a => a.status === 'working').length;
  };

  const getAverageEfficiency = () => {
    if (agents.length === 0) return 0;
    const totalEfficiency = agents.reduce((sum, agent) => sum + agent.efficiency, 0);
    return Math.round((totalEfficiency / agents.length) * 100);
  };

  return (
    <div className="fixed top-4 left-1/2 transform -translate-x-1/2 z-20 pointer-events-auto">
      <Card className="bg-black bg-opacity-90 border-cyan-500 glow-cyan">
        <CardContent className="py-2 px-4">
          <div className="flex items-center space-x-6 text-sm">
            {/* Game Status */}
            <div className="flex items-center space-x-2">
              <div className={`w-2 h-2 rounded-full ${
                gamePhase === 'playing' ? 'bg-green-400' : 'bg-yellow-400'
              }`} />
              <span className="text-cyan-300 font-mono">
                {gamePhase === 'playing' ? 'ACTIVE' : 'PAUSED'}
              </span>
            </div>

            {/* Game Timer */}
            <div className="text-cyan-400 font-mono">
              <span className="text-cyan-300">TIME:</span>
              <span className="ml-1 text-white font-bold">{formatTime(gameTime)}</span>
            </div>

            {/* NRN Balance */}
            <div className="text-cyan-400 font-mono">
              <span className="text-cyan-300">NRN:</span>
              <span className="ml-1 text-green-400 font-bold">{nrnBalance.toFixed(1)}</span>
            </div>

            {/* Network Stats */}
            <div className="flex space-x-4 text-xs">
              <div className="text-cyan-300">
                <span className="text-cyan-400">Agents:</span>
                <span className="ml-1 text-blue-400">{getActiveAgentsCount()}/{agents.length}</span>
              </div>

              <div className="text-cyan-300">
                <span className="text-cyan-400">Efficiency:</span>
                <span className="ml-1 text-yellow-400">{getAverageEfficiency()}%</span>
              </div>

              <div className="text-cyan-300">
                <span className="text-cyan-400">Health:</span>
                <span className={`ml-1 ${getNetworkHealth() > 70 ? 'text-green-400' : 
                  getNetworkHealth() > 40 ? 'text-yellow-400' : 'text-red-400'}`}>
                  {getNetworkHealth()}%
                </span>
              </div>
            </div>

            {/* Control Buttons */}
            <div className="flex space-x-2">
              {gamePhase === 'playing' ? (
                <Button
                  onClick={pauseGame}
                  size="sm"
                  className="bg-yellow-600 hover:bg-yellow-700 text-white text-xs px-2 py-1"
                >
                  PAUSE
                </Button>
              ) : (
                <Button
                  onClick={startGame}
                  size="sm"
                  className="bg-green-600 hover:bg-green-700 text-white text-xs px-2 py-1"
                >
                  RESUME
                </Button>
              )}
            </div>
          </div>

          {/* Secondary stats bar */}
          <div className="flex justify-between items-center mt-2 pt-2 border-t border-cyan-700 text-xs">
            <div className="flex space-x-4">
              <span className="text-red-400">
                <span className="text-red-300">ErrorNodes:</span> {errorNodes.filter(n => !n.isBeingSolved).length}
              </span>
              <span className="text-green-400">
                <span className="text-green-300">SkillNodes:</span> {skillNodes.length}
              </span>
              <span className="text-purple-400">
                <span className="text-purple-300">Resolved:</span> {errorsResolved}
              </span>
            </div>

            <div className="text-cyan-400">
              <span className="text-cyan-300">Network:</span> KNIRV D-TEN
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

